from collections.abc import Mapping
from typing import Literal, NotRequired, TypedDict


class ImageSize(TypedDict):
    """ImageSize in calib.schema.json."""

    w: int
    h: int


class Camera(TypedDict):
    """The camera block (contract §4.1). Ranges are clamped by every writer."""

    fov_y_deg: float
    height_m: float
    pitch_deg: float
    roll_deg: float


class CalibFloor(TypedDict):
    """CalibFloor in calib.schema.json.

    Open: the schema allows keys not listed here."""

    found: bool
    # Share of the image's pixels that lie on the fitted floor plane.
    inlier_ratio: NotRequired[float | None]
    # RMS distance of the inliers to the plane, meters.
    rmse_m: NotRequired[float | None]


class CalibDepth(TypedDict):
    """CalibDepth in calib.schema.json."""

    file: Literal["depth.png"]
    w: int
    h: int
    floor_masked: bool


class CalibExif(TypedDict):
    """CalibExif in calib.schema.json.

    Open: the schema allows keys not listed here."""

    focal_35mm: NotRequired[float | None]
    # Vertical FOV from focal_35mm (native 4:3 frame, then the crop that keeps the width).
    fov_y_deg: NotRequired[float | None]
    make: NotRequired[str | None]
    model: NotRequired[str | None]


class CalibFovDisagreement(TypedDict):
    """Present when MoGe's and the EXIF vertical FOV differ by more than 8 degrees.

    Open: the schema allows keys not listed here."""

    moge_deg: float
    exif_deg: float


class Calib(TypedDict):
    """Written by `midstudy-calib fit` (and `run`). `midstudy-calib run` prints the same object plus "ok": true as its
    last stdout line. Keys not listed here are allowed for diagnostics; readers ignore them.

    Open: the schema allows keys not listed here."""

    version: Literal[1]
    # Only on the stdout line of `run` / `fit`, never in the file.
    ok: NotRequired[Literal[True]]
    # moge-2: MoGe fitted the camera; exif: fallback with the FOV from the EXIF focal length; default: fallback
    # with FOV 55; truth: golden scenes only (fixtures/scenes).
    source: Literal["moge-2", "exif", "default", "truth"]
    # The MoGe weights used, e.g. Ruicheng/moge-2-vitl-normal; null when MoGe didn't run.
    model: str | None
    # photo.jpg's size in pixels (after EXIF orientation and downsizing).
    image: ImageSize
    camera: Camera
    # Principal point as a fraction of width and height. Recorded, but v1 always renders with the image center.
    principal: list[float]
    floor: CalibFloor
    # depth.png next to calib.json: 16-bit grayscale, mm along the camera's view axis, 0 = no occluder (floor
    # within 4 cm of the plane, sky, unknown). Null when there is no depth (fallbacks, --no-depth).
    depth: CalibDepth | None
    # What the upload's EXIF said, read from source.<ext> (photo.jpg has no metadata). Null without EXIF.
    exif: CalibExif | None
    # Whose FOV the camera uses: the photo's EXIF focal length (when it agrees with MoGe's within 8 degrees;
    # MoGe's scale is then corrected by the focal ratio, contract §4.3 Fit) or MoGe's own. Absent on mock,
    # fallback and truth calibrations.
    fov_source: NotRequired[Literal["exif", "moge"]]
    # MoGe-2's own estimates and timings (fov_x_deg, fov_y_deg, input, load_s, infer_s, floor_fit_s) and, with
    # fov_source exif, the correction: height_m (MoGe's own), scale (tan(fov_moge/2) / tan(fov_exif/2)),
    # depth_scale.
    moge: NotRequired[Mapping[str, object]]
    # Present when MoGe's and the EXIF vertical FOV differ by more than 8 degrees.
    fov_disagreement: NotRequired[CalibFovDisagreement]
    device: Literal["mps", "cuda", "cpu"] | None
    elapsed_s: float


type Rgb = list[float]


type UnitVector = list[float]


class LightingAmbient(TypedDict):
    """LightingAmbient in lighting.schema.json.

    Open: the schema allows keys not listed here."""

    # L2 spherical harmonics, three.js SphericalHarmonics3 order [L00, L1-1 (y), L10 (z), L11 (x), L2-2, L2-1,
    # L20, L21, L22], radiance coefficients as THREE.LightProbe takes them, camera frame, RGB. The key light is
    # not included.
    sh: list[list[float]]


class LightingKey(TypedDict):
    """LightingKey in lighting.schema.json.

    Open: the schema allows keys not listed here."""

    # Unit vector towards the light, camera frame.
    direction: UnitVector
    # Linear RGB, largest component 1.
    color: Rgb
    # THREE.DirectionalLight intensity.
    intensity: float
    # 0 a hard sun edge, 1 very diffuse.
    softness: float
    # How clearly the photo shows one directional light.
    confidence: float


